```javascript
const axios = require('axios'); // Make sure to install axios package using npm or yarn before running the code

async function sendMessageToSlack(text, channel) {
  try {
    const options = {
      method: 'post',
      url: `https://slack.com/api/chat.postMessage`,
      headers: { 'Content-Type': 'application/json' },
      data: {
        channel: channel,
        text: text,
      },
    };

    const response = await axios(options);

    if (response.status === 200) {
      console.log(`Message sent to channel #${channel}: ${text}`);
    } else {
      throw new Error(`Error sending message to Slack: ${response.statusText}`);
    }
  } catch (error) {
    console.error(`Error sending message to Slack: ${error.message}`);
  }
}

// Example usage:
sendMessageToSlack('Hello, world!', '#general');
