Here's a simple Swift script that reads the input text from a file, identifies homophones, and replaces them with their correct forms:

```swift
import Foundation

// Define a dictionary of homophones and their correct forms
let homophoneDictionary: [String: String] = [
    "their": "they're",
    "know": "no, know",
    "weigh": "weight",
    "to": "too",
    "no": "know, no",
    "is": "is",
    "it": "it",
    "seam": "seem",
    "be": "be",
    "eye": "I",
    "knot": "not",
    "aloud": "allow",
    "right": "write",
    "butt": "but",
    "sum": "some",
    "difference": "differences",
    "deniy": "deny",
    "common": "commonly"
]

func replaceHomophones(_ text: String) -> String {
    let words = text.components(separatedBy: " ")
    var newWords: [String] = []

    for word in words {
        guard let replacement = homophoneDictionary[word.lowercased()] else {
            newWords.append(word)
            continue
        }

        newWords.append(replacement)
    }

    return newWords.joined(separator: " ")
}

