class BaseModel2(models.Model):
    column_a = models.CharField(max_length=255)
    column_b = models.IntegerField()
```

Next, we create derived models that inherit from these base models and use metaclasses to dynamically set their columns based on a configuration setting:

```python
import django.db as db

CONFIG = 'model1'  # Change this to switch between models

class DynamicModel(type):
    def __new__(mcs, name, bases, attrs):
        model = super().__new__(mcs, name, bases, attrs)

        if CONFIG == 'model1':
            model.Meta.db_table = 'tablename1'
            model._meta.fields += (
                'column_x', models.CharField(max_length=255),
                'column_y', models.IntegerField(),
            )
        elif CONFIG == 'model2':
            model.Meta.db_table = 'tablename2'
            model._meta.fields += (
                'column_a', models.CharField(max_length=255),
                'column_b', models.IntegerField(),
            )

        return model

@receiver(signals.post_init)
